export const RELEASES=[{version:'1.4.0',date:'1 Kasım 2026',title:'Daha kompakt menü ve yeni oda sırası',items:['Masaüstü menüsü ekran yüksekliğine uyarlanır; daha küçük kartlar ve kontroller.','Pin Sorgula menüden kaldırıldı. SPVS-1 ilk sıraya alındı, Boss odası kaldırıldı.','FFA-10’dan sonra Etkinlik-1, Alan-1 ve yeni Alan-2 sıralanır.','Oyun ekranında skor, Gold, sonuç duyuruları ve sağ alt bilgiler yeniden yerleştirildi.']},{version:'1.3.0',date:'1 Kasım 2026',title:'Rekorların son 5 dakikasını izle',items:['Tekrarlar ayrı sekmede açılır; duraklatma, sarma ve hız seçimi vardır.','Onur Tablosu rekor sahibinin turda kullandığı skini gösterir.','Sayfam kupa kartı, Gold/Bonus satırları ve renkli galibiyet kutularıyla yenilendi.','ZirvePass fiyatı 5.000.000 Gold oldu.']}];
export function releaseNews({esc}){const r=RELEASES[0];return `<b>${esc(r.title)}</b><p>Sürüm ${esc(r.version)} · ${esc(r.date)}</p><ul>${r.items.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><button data-page="updates">Tüm güncelleme notları →</button>`}
export function releaseHistory({esc}){return `<div class="doc"><h2>Son Güncellemeler</h2>${RELEASES.map(r=>`<section class="sub-card"><small>${esc(r.date)} · ${esc(r.version)}</small><h3>${esc(r.title)}</h3><ul>${r.items.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></section>`).join('')}</div>`}
